using BookOfEternityClient.Services;

namespace BookOfEternityClient.Core;

public partial class GameEngine
{
    // A settled owning result is separate from the old homogeneous transaction.
    // The witness below is diagnostic, never permission to take/replay a plan.
    private sealed record MortalJointRepairCanonicalRefresh(
        MortalJointRepairPublicationDisposition Disposition,
        AcceptedMechanicsPlan? Plan,
        IReadOnlyList<ValidationIssue> Issues,
        MortalQteDecisionPublication.JointCompletedWitness? Completed = null,
        ValidatedPendingTurnSnapshotContext? Frame = null);

    private MortalJointRepairCanonicalRefresh? _mortalJointRepairCanonicalRefresh;

    private async Task<MortalJointRepairCanonicalRefresh> PublishCurrentMortalJointRepairAsync(
        ValidatedPendingTurnSnapshotContext frame, int expectedTurn,
        IReadOnlyDictionary<string, string> backups)
    {
        if (!MatchesMortalJointRepairFrame(frame, expectedTurn) || !_mortalJointRepairCorrectionReady)
            throw new InvalidDataException("Joint canonical publication requires the actual corrected admitted frame.");
        if (_mortalJointRepairCanonicalRefresh is { Disposition: MortalJointRepairPublicationDisposition.Committed or
            MortalJointRepairPublicationDisposition.PublicationUncertain })
            throw new InvalidDataException("A retained joint committed/uncertain attempt requires its dedicated recovery route, not a second publication.");
        MortalJointRepairCanonicalRefresh result;
        await using (var lease = await _fs.AcquireCanonicalWriteLeaseAsync())
        {
            RequireOrdinaryJointRepairLease(lease);
            // The raw intake lease owns no plan. Reconstruct BOTH owners and the
            // still-confirmed original request here, under the canonical lease.
            var intake = await InspectOrdinaryMortalJointRepairAsync(lease, frame, expectedTurn);
            if (intake.Disposition != MortalJointRepairRawDisposition.Owned)
                return Retain(new(MortalJointRepairPublicationDisposition.PublicationUncertain, null, intake.Issues));
            await intake.ValidateCurrentAsync(_fs, lease, frame.SessionId, frame.RequestId,
                frame.Payload.ManifestPayloadHash, expectedTurn);
            var capture = await ReadCurrentJointRejectedCaptureAsync(lease, _mortalJointRepairCheckpoint!.ToJsonObject());
            var preparation = await WoundAcceptedTurnPlanner.CreateJointRepairPreparationAsync(_fs, lease, capture);
            if (!preparation.IsValid)
                return Retain(new(MortalJointRepairPublicationDisposition.PublicationUncertain, null, preparation.Issues));
            var continuation = preparation.Authority!;
            object? reservationAuthority = null;
            var publicationEntered = false;
            try
            {
                var reservation = await AcceptedTurnAuthorityRegistry.ReserveMortalJointRepairPublicationAsync(_fs, lease, continuation);
                if (reservation.Authority is null || reservation.Status is not
                    (MortalWoundTreatmentPublicationReservationStatus.Reserved or MortalWoundTreatmentPublicationReservationStatus.Exact))
                    throw new InvalidDataException("The same joint owner could not reserve its exclusive publication slot.");
                reservationAuthority = reservation.Authority;
                var prepared = await AcceptedTurnAuthorityRegistry.GetOrBuildWoundJointRepairPreparedValidatedAsync(
                    _fs, lease, preparation.Input!, continuation, reservationAuthority);
                if (!prepared.Success || prepared.Plan is not { } preparedPlan) return Refused(prepared.Issues);
                var effectInput = WoundAcceptedTurnPlanner.ComposeJointRepairEffectInput(preparedPlan);
                var effects = await AcceptedTurnAuthorityRegistry.GetOrBuildWoundJointRepairEffectValidatedAsync(
                    _fs, lease, preparedPlan, effectInput, continuation, reservationAuthority);
                if (!effects.Success || effects.Plan is not { } effectPlan) return Refused(effects.Issues);
                var final = await AcceptedTurnAuthorityRegistry.GetOrBuildWoundJointRepairFinalValidatedAsync(
                    _fs, lease, preparedPlan, effects, continuation, reservationAuthority);
                if (!final.Success || final.Plan is not { } finalPlan) return Refused(final.Issues);
                var bundle = new AcceptedMechanicsWoundStageBundle(preparation.Input!, preparedPlan, effectPlan, finalPlan);
                var anchors = MortalWoundCanonicalAnchorPlan.CreateJointRepair(_fs, lease, bundle);
                if (!anchors.Success || anchors.Plan is null) return Refused(anchors.Issues);
                var mechanical = await CreateMortalJointRepairMechanicalAdmissionAsync(lease, frame, bundle, continuation);
                var baseline = await WoundAcceptedTurnPlanner.CreateJointRepairCommonBaselineAsync(
                    _fs, lease, mechanical, bundle, anchors.Plan, continuation, reservationAuthority);
                if (!baseline.IsValid) return Refused(baseline.Issues);
                var resources = await WoundAcceptedTurnPlanner.CreateJointRepairResourcePublicationAsync(_fs, lease, baseline.Authority!);
                if (!resources.IsValid) return Refused(resources.Issues);
                // Freeze and authenticate progression BEFORE the common input,
                // cache fingerprint and take. No after-seal acknowledgement may
                // attach to the already-issued mechanics candidate.
                var progression = await CaptureMortalJointProgressionSourceAsync(lease, frame);
                var common = await WoundAcceptedTurnPlanner.CreateJointRepairCommonPlanAsync(_fs, lease, resources.Authority!, progression);
                if (!common.Success || common.Plan is not { } commonPlan) return Refused(common.Issues);
                var bound = _normalizer.BindTo(lease);
                var preflight = await bound.PrevalidateJointRepairPublicationTransactionAsync() ??
                    throw new InvalidDataException("The exact complete joint common plan was not preflighted.");
                if (preflight.Validated.Plan.InputFingerprint != commonPlan.InputFingerprint ||
                    preflight.Validated.Plan.PreparedPlanFingerprint != commonPlan.PreparedPlanFingerprint)
                    throw new InvalidDataException("Joint canonical preflight no longer selects the same complete common candidate.");
                // From here only the owning transaction can classify/compensate
                // attempted publication. A generic catch must never abort/rearm it.
                publicationEntered = true;
                var published = await bound.NormalizeAndValidateJointRepairAsync(preflight, _validator, backups);
                result = Retain(new(published.Disposition, published.Plan, published.Issues));
                if (published.Disposition == MortalJointRepairPublicationDisposition.Committed)
                {
                    // Retain Committed BEFORE this additional diagnostic read.
                    // Its failure cannot reinterpret a finalized hold as rollback.
                    var witness = await MortalQteDecisionPublication.ReadJointCompletedWitnessAsync(_fs, lease,
                        frame.SessionId, frame.RequestId, frame.Payload.ManifestPayloadHash, expectedTurn);
                    result = Retain(result with { Completed = witness });
                }
                lease.EnsureNoPendingLocalDecision();
            }
            catch (Exception error) when (error is not SessionReplacedException &&
                error is InvalidDataException or IOException or InvalidOperationException or ArgumentException or
                    System.Text.Json.JsonException or AggregateException or OperationCanceledException)
            {
                if (!publicationEntered && reservationAuthority is not null)
                    AcceptedTurnAuthorityRegistry.AbortMortalJointRepairPublication(_fs, lease, continuation, reservationAuthority);
                var existing = _mortalJointRepairCanonicalRefresh;
                result = Retain(new(existing?.Disposition == MortalJointRepairPublicationDisposition.Committed
                    ? MortalJointRepairPublicationDisposition.Committed : MortalJointRepairPublicationDisposition.PublicationUncertain,
                    existing?.Plan, JointRepairAdmissionIssue(error.Message), existing?.Completed));
            }

            MortalJointRepairCanonicalRefresh Refused(IReadOnlyList<ValidationIssue> issues)
            {
                AcceptedTurnAuthorityRegistry.AbortMortalJointRepairPublication(_fs, lease, continuation, reservationAuthority!);
                return Retain(new(MortalJointRepairPublicationDisposition.PublicationUncertain, null, issues));
            }
        }
        // Runtime reads occur only after the participating canonical lease closes.
        if (result.Disposition == MortalJointRepairPublicationDisposition.Committed && result.Completed is not null)
            await RefreshRuntimeStateAsync();
        return result;

        MortalJointRepairCanonicalRefresh Retain(MortalJointRepairCanonicalRefresh value) =>
            _mortalJointRepairCanonicalRefresh = value with { Frame = frame };
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using BookOfEternityClient.Configuration;
using BookOfEternityClient.Models;
using BookOfEternityClient.Services;

namespace BookOfEternityClient.Core;

public partial class GameEngine
{
    private static readonly object JointMechanicalAdmissionIssuer = new();

    // The private validated frame never leaves GameEngine. This proof is issued
    // from actual bytes, not from a caller GameResponse or bare frame coordinates.
    internal sealed class MortalJointRepairMechanicalAdmission
    {
        private readonly FileSystemManager _files;
        private readonly FileSystemManager.CanonicalWriteLease _lease;
        private readonly Dictionary<string, byte[]?> _before;
        private readonly WoundAcceptedTurnBinding _binding;
        private readonly string _generation;
        internal MortalJointRepairMechanicalAdmission(object issuer, FileSystemManager files,
            FileSystemManager.CanonicalWriteLease lease, string generation, WoundAcceptedTurnBinding binding,
            IReadOnlyDictionary<string, byte[]?> before)
        {
            if (!ReferenceEquals(issuer, JointMechanicalAdmissionIssuer))
                throw new InvalidOperationException("Mechanical admission requires its actual GameEngine owner.");
            _files = files; _lease = lease; _generation = generation;
            _binding = WoundAcceptedTurnData.CloneBinding(binding)!;
            _before = before.ToDictionary(row => row.Key, row => row.Value?.ToArray(), StringComparer.Ordinal);
            Fingerprint = ComputeFingerprint();
        }
        internal string Fingerprint { get; }
        internal IReadOnlyDictionary<string, CanonicalBeforeImage> BeforeImages => _before.ToDictionary(
            row => row.Key, row => new CanonicalBeforeImage(row.Value is not null, row.Value?.ToArray()), StringComparer.Ordinal);
        private string ComputeFingerprint()
        {
            var fields = new List<string?> { "book_of_eternity.mortal_joint_repair.mechanical_admission.v1",
                _generation, WoundAcceptedTurnFingerprints.ComputeBinding(_binding) };
            foreach (var (path, bytes) in _before.OrderBy(row => row.Key, StringComparer.Ordinal))
            { fields.Add(path); fields.Add(bytes is null ? null : Convert.ToHexString(SHA256.HashData(bytes))); }
            return WoundAcceptedTurnFingerprintWriter.Compute(fields);
        }
        internal async Task ValidateCurrentAsync(FileSystemManager files, FileSystemManager.CanonicalWriteLease lease,
            WoundAcceptedTurnBinding binding)
        {
            files.EnsureCanonicalWriteLeaseActive(lease);
            if (!ReferenceEquals(files, _files) || !ReferenceEquals(lease, _lease) ||
                !files.IsCurrentSessionGeneration(lease, _generation) || ComputeFingerprint() != Fingerprint ||
                WoundAcceptedTurnFingerprints.ComputeBinding(binding) != WoundAcceptedTurnFingerprints.ComputeBinding(_binding))
                throw new InvalidDataException("Joint mechanical admission belongs to a stale or foreign owner/frame.");
            var original = MortalQteWoundOpportunityProjection.ReadSnapshot(files, lease);
            if (original.SessionId != binding.SessionId || original.RequestId != binding.RequestId ||
                original.SnapshotToken != binding.SnapshotToken || original.TurnNumber != binding.Turn || original.Realm != binding.Realm)
                throw new InvalidDataException("The official original no longer matches mechanical admission.");
            foreach (var (path, expected) in _before)
            {
                var current = await files.ReadFileBytesAsync(lease, path);
                if (expected is null ? current is not null : current is null || !expected.AsSpan().SequenceEqual(current))
                    throw new InvalidDataException("Joint mechanical admission changed: " + path);
            }
        }
        internal async Task<GameResponse> ReadProvedEmptyResponseAsync(FileSystemManager files,
            FileSystemManager.CanonicalWriteLease lease, WoundAcceptedTurnBinding binding)
        {
            await ValidateCurrentAsync(files, lease, binding);
            // The owner below independently proved every concurrent mechanical input
            // empty/unchanged. This is not a stripped display response or omission.
            return new GameResponse();
        }
    }

    // Called by the fresh canonical joint owner after real resource admission.
    // Its private actual frame never crosses into a caller-supplied envelope.
    private async Task<MortalJointRepairMechanicalAdmission> CreateMortalJointRepairMechanicalAdmissionAsync(
        FileSystemManager.CanonicalWriteLease lease, ValidatedPendingTurnSnapshotContext frame,
        AcceptedMechanicsWoundStageBundle bundle, object continuation)
    {
        _fs.EnsureCanonicalWriteLeaseActive(lease);
        if (!ReferenceEquals(bundle.PreparedPlan.JointRepairContinuationAuthority, continuation) ||
            !WoundAcceptedTurnPlanner.JointRepairFinalPlanAgrees(bundle))
            throw new InvalidDataException("Mechanical admission requires the actual complete private joint stages.");
        await WoundAcceptedTurnPlanner.ValidateJointRepairCurrentAsync(_fs, lease, continuation);
        var binding = bundle.Input.Binding;
        var paths = AcceptedMechanicsWoundCommonInputComposer.TreatmentOrdinaryGuardPaths.Concat(new[]
            { NpcTradeRequestState.PendingRequestPath, TrainingRequestState.PendingRequestPath, MortalQteDecisionPublication.StatePath })
            .Concat(MortalJointInactiveTailPaths)
            .Concat(WoundAcceptedTurnSnapshotContract.CarrierPaths)
            .Concat(bundle.EffectBatchPlan.EffectPlan.CarrierBeforeImages.Keys)
            .Concat(bundle.EffectBatchPlan.EffectPlan.TouchedPaths)
            .Concat(bundle.EffectBatchPlan.EffectPlan.DeletedPaths)
            .Distinct(StringComparer.Ordinal).ToArray();
        var read = PendingTurnSnapshotReader.ReadCurrent(_fs, lease, new PendingTurnSnapshotPathSelection(
            new[] { "game_state/meta/soul_state.json" }, paths.Where(path => path != "game_state/meta/soul_state.json" &&
                path != MortalWoundOpportunityAdapter.DecisionPath)));
        if (!read.Success || read.Snapshot is not { } original)
            throw new InvalidDataException("Joint mechanical original read failed: " + string.Join(";", read.Issues.Select(row => row.Code)));
        if (binding.Realm != "mortal_world" || original.SessionId != frame.SessionId || original.RequestId != frame.RequestId ||
            original.SnapshotToken != frame.Payload.ManifestPayloadHash || original.TurnNumber != frame.TurnNumber ||
            original.SessionId != binding.SessionId || original.RequestId != binding.RequestId ||
            original.SnapshotToken != binding.SnapshotToken || original.TurnNumber != binding.Turn || original.Realm != binding.Realm)
            throw new InvalidDataException("The actual validated frame and official original must agree with both joint owners.");
        var before = new Dictionary<string, byte[]?>(StringComparer.Ordinal);
        foreach (var path in paths)
        {
            var current = await _fs.ReadFileBytesAsync(lease, path);
            before.Add(path, current);
            // Exactly this already authenticated public draft is owned by the real
            // adapter/private preparation. It grants no exemption to other work.
            if (path == MortalWoundOpportunityAdapter.DecisionPath) continue;
            if (path == "game_state/meta/guardians.json") continue;
            if (path == ResourceMaterializationContract.CommandPath || path == EffectAcceptedTurnPlan.CommandPath)
            {
                if (current is not null) throw new InvalidDataException("Joint concurrent command is unsupported: " + path);
                continue;
            }
            if (!original.CoveredLogicalPaths.Contains(path, StringComparer.Ordinal))
            {
                if (current is not null) throw new InvalidDataException("Uncovered joint mechanical input is present: " + path);
                // Refusal-only absence never grants pristine canonical authority.
                continue;
            }
            if (current is null || !JsonNode.DeepEquals(ReadJointMechanicalNode(original.ReadRequiredBytes(path), path),
                    ReadJointMechanicalNode(current, path)))
                throw new InvalidDataException("Concurrent joint mechanical input changed: " + path);
        }
        foreach (var path in new[] { AcceptedMechanicsPlan.WoundCommandPath, WoundAcceptedTurnSnapshotContract.PendingResolutionPath,
            "output/narrative_response.json", LiveTurnPreparationService.TurnRequestPath,
            LiveTurnPreparationService.PendingTurnSnapshotManifestPath, PendingTurnSnapshotAuthority.AuthorityPath })
            before.TryAdd(path, await _fs.ReadFileBytesAsync(lease, path));
        // Complete current guard coverage separately from original-source admission:
        // current GM-owned outputs need not equal their signed original images.
        foreach (var path in WoundAcceptedTurnSnapshotContract.RequiredPaths)
        {
            var current = await _fs.ReadFileBytesAsync(lease, path);
            if (before.TryGetValue(path, out var captured))
            {
                if (captured is null ? current is not null : current is null || !captured.AsSpan().SequenceEqual(current))
                    throw new InvalidDataException("Joint required before-image changed during capture: " + path);
            }
            else before.Add(path, current);
        }
        // Unchanged bytes alone are not no-work evidence. Prove the approved
        // inactive completion tail BEFORE common fingerprints/cache/take.
        RequireInactiveMortalJointTail(before, binding.Turn);
        // Revalidate exact owned command/pending/draft/scene after the complete read.
        await WoundAcceptedTurnPlanner.ValidateJointRepairCurrentAsync(_fs, lease, continuation);
        var proof = new MortalJointRepairMechanicalAdmission(JointMechanicalAdmissionIssuer, _fs, lease,
            _fs.ReadLocalGenerationSnapshot(lease).Binding.Id, binding, before);
        await proof.ValidateCurrentAsync(_fs, lease, binding);
        return proof;
    }

using System.Text.Json.Nodes;
using BookOfEternityClient.Configuration;
using BookOfEternityClient.Services;

namespace BookOfEternityClient.Core;

public partial class GameEngine
{
    // Refusal-only guards for the approved first joint contour. Absence here
    // creates no canonical state, request, claim or pristine authority.
    internal static IReadOnlyList<string> MortalJointInactiveTailPaths { get; } = Array.AsReadOnly(new[]
    {
        "game_state/player/status_changes.json", "game_state/player/stat_points.json",
        "game_state/player/experience.json", "game_state/core/player_status.json",
        QteSceneService.QteOfferPath, QteSceneService.QteRuntimePath, QteDeferredEffectContinuation.StatePath
    });

    internal static async Task ValidateCurrentMortalJointInactiveTailAsync(FileSystemManager files,
        FileSystemManager.CanonicalWriteLease lease, int decisionTurn)
    {
        files.EnsureCanonicalWriteLeaseActive(lease);
        var images = new Dictionary<string, byte[]?>(StringComparer.Ordinal);
        foreach (var path in MortalJointInactiveTailPaths) images.Add(path, await files.ReadFileBytesAsync(lease, path));
        RequireInactiveMortalJointTail(images, decisionTurn);
    }

    private static void RequireInactiveMortalJointTail(IReadOnlyDictionary<string, byte[]?> images, int decisionTurn)
    {
        if (decisionTurn <= 0) throw new InvalidDataException("Joint tail requires its actual positive decision turn.");
        JsonObject? Read(string path) => images[path] is { } bytes
            ? StrictJsonAuthority.Deserialize<JsonObject>(CanonicalJsonUtf8.DecodeOneOptionalBom(bytes),
                SharedJsonOptions.PrettyCamelCaseUnsafeRelaxed, path) ?? throw new InvalidDataException("Present joint tail JSON null: " + path)
            : null;
        var changes = Read("game_state/player/status_changes.json");
        if (changes?["statsIncreased"] is { } stats && (stats is not JsonArray array || array.Count != 0))
            throw new InvalidDataException("The first joint contour cannot own pending statsIncreased work.");

        // Match the actual CheckLevelUp source priority. Missing optional level
        // fields have its existing baseline of one; a present invalid field is
        // refused instead of manufacturing processed-level evidence.
        var experience = Read("game_state/player/experience.json");
        var level = OptionalPositiveLevel(experience, "level");
        if (level is null) level = OptionalPositiveLevel(experience, "playerLevel");
        if ((level ?? 1) <= 1) level = OptionalPositiveLevel(Read("game_state/core/player_status.json"), "level") ?? 1;
        var points = Read("game_state/player/stat_points.json") ??
            throw new InvalidDataException("Joint completion requires an existing durable processed-level marker; no stat initialization.");
        if (points["levelUpStatPointsAwardedThroughLevel"] is not JsonValue processed ||
            !processed.TryGetValue<int>(out var through) || through < level.Value)
            throw new InvalidDataException("The first joint contour cannot own an unprocessed level-up or stat-point initialization/award.");
        if (points.ContainsKey("unspentStatPoints") && (points["unspentStatPoints"] is not JsonValue unspent ||
            !unspent.TryGetValue<int>(out var quantity) || quantity < 0))
            throw new InvalidDataException("Joint tail stat-point state is malformed.");

        if (images[QteSceneService.QteOfferPath] is not null)
            throw new InvalidDataException("The first joint contour cannot own a new QTE offer for its decision turn.");
        if (images[QteSceneService.QteRuntimePath] is { } runtimeBytes)
        {
            var runtime = StrictJsonAuthority.Deserialize<QteSceneService.QteRuntimeState>(CanonicalJsonUtf8.DecodeOneOptionalBom(runtimeBytes),
                SharedJsonOptions.PrettyCamelCaseUnsafeRelaxed, "actual joint QTE runtime") ??
                throw new InvalidDataException("Present joint QTE runtime is null.");
            if (runtime.PendingOffer is not null || runtime.ActiveScene is not null)
                throw new InvalidDataException("The first joint contour cannot own a pending/active QTE runtime handoff.");
        }
        if (Read(QteDeferredEffectContinuation.StatePath) is { } deferred)
        {
            if (deferred["state"]?.GetValue<string>() != "terminal" ||
                deferred["clientStoryAppend"]?["source"] is not JsonObject source ||
                source["turnNumber"] is not JsonValue turn || !turn.TryGetValue<int>(out var priorTurn) ||
                priorTurn <= 0 || priorTurn >= decisionTurn)
                throw new InvalidDataException("Only the different prior finalized QTE source may remain in the joint completion tail.");
        }
    }

    private static int? OptionalPositiveLevel(JsonObject? root, string field)
    {
        if (root is null || !root.ContainsKey(field)) return null;
        if (root[field] is JsonValue value && value.TryGetValue<int>(out var level) && level > 0) return level;
        throw new InvalidDataException("Joint tail canonical level is malformed: " + field);
    }
}

private async Task<MortalJointRepairRawAdmission> InspectOrdinaryMortalJointRepairAsync(
    FileSystemManager.CanonicalWriteLease lease, ValidatedPendingTurnSnapshotContext frame, int expectedTurn)
{
    _fs.EnsureCanonicalWriteLeaseActive(lease);
    var guards = new Dictionary<string, byte[]?>(StringComparer.Ordinal);
    MortalJointRepairRawAdmission Result(MortalJointRepairRawDisposition disposition,
        MortalJointRepairCheckpoint.RejectedCapture? capture, IReadOnlyList<ValidationIssue> issues) =>
        new(MortalJointRepairRawIssuer, _fs, lease, disposition, capture, guards, issues);
    try
    {
        var commandBytes = await _fs.ReadFileBytesAsync(lease, AcceptedMechanicsPlan.WoundCommandPath);
        var pendingBytes = await _fs.ReadFileBytesAsync(lease, WoundAcceptedTurnSnapshotContract.PendingResolutionPath);
        var draftBytes = await _fs.ReadFileBytesAsync(lease, MortalWoundOpportunityAdapter.DecisionPath);
        var hasCheckpoint = _mortalJointRepairCheckpoint is not null;
        var pending = pendingBytes is null ? null : ReadOrdinaryTreatmentRoot(pendingBytes, "joint intake private wave");
        hasCheckpoint |= pending?["jointRepairCheckpoint"] is not null;
        if (!hasCheckpoint && (commandBytes is null || draftBytes is null))
            return Result(MortalJointRepairRawDisposition.NotApplicable, null, Array.Empty<ValidationIssue>());
        if (commandBytes is null)
            return Result(MortalJointRepairRawDisposition.Rejected, null, JointRepairAdmissionIssue("The exact held treatment command is missing."));
        var parsed = WoundResponseInputComposer.ParseCommandRoot(JsonSerializer.SerializeToElement(
            ReadOrdinaryTreatmentRoot(commandBytes, "joint intake command")));
        if (!hasCheckpoint && parsed.TreatmentCommands.Count == 0)
            return Result(MortalJointRepairRawDisposition.NotApplicable, null, Array.Empty<ValidationIssue>());
        if (!parsed.Success || parsed.TreatmentCommands.Count != 1 || parsed.Commands.Count != 0 || parsed.AcceptedTransitionCommands.Count != 0)
            return Result(MortalJointRepairRawDisposition.Rejected, null, JointRepairAdmissionIssue("One exact homogeneous guaranteed treatment command is required."));
        var captured = pending?["jointRepairCheckpoint"] is not null
            ? await MortalJointRepairCheckpoint.ReconstructAsync(_fs, lease, frame.SessionId, frame.RequestId, frame.Payload.ManifestPayloadHash, expectedTurn)
            : await MortalJointRepairCheckpoint.CaptureAsync(_fs, lease, frame.SessionId, frame.RequestId, frame.Payload.ManifestPayloadHash, expectedTurn);
        if (!captured.IsValid || captured.Capture is not { } capture)
            return Result(MortalJointRepairRawDisposition.Rejected, null,
                captured.Issues.Select(MortalWoundOpportunityAdapter.PrivateSourceIssue).ToArray());
        if (frame.TurnNumber != expectedTurn || _mortalJointRepairCheckpoint is { } retained &&
            !JsonNode.DeepEquals(retained.ToJsonObject(), capture.Checkpoint.ToJsonObject()))
            return Result(MortalJointRepairRawDisposition.Rejected, null, JointRepairAdmissionIssue("The original source/request/checkpoint cannot change during this repair."));
        _mortalJointRepairCheckpoint ??= capture.Checkpoint;
        foreach (var path in new[] { AcceptedMechanicsPlan.WoundCommandPath, WoundAcceptedTurnSnapshotContract.PendingResolutionPath,
            MortalWoundOpportunityAdapter.DecisionPath, WoundNarrativeOutputPath,
            LiveTurnPreparationService.PendingTurnSnapshotManifestPath, PendingTurnSnapshotAuthority.AuthorityPath })
            guards[path] = await _fs.ReadFileBytesAsync(lease, path);
        if (pending?["jointRepairCheckpoint"] is null || draftBytes is null)
            return Result(MortalJointRepairRawDisposition.Rejected, capture, capture.RejectedIssues.Select(BindMortalQteDraftRepairTarget).ToArray());
        var current = ReadOrdinaryTreatmentRoot(draftBytes, "joint public correction");
        var rejected = ReadOrdinaryTreatmentRoot(Convert.FromBase64String(capture.Checkpoint.ToJsonObject()["rejectedDraftBase64"]!.GetValue<string>()), "joint retained rejected draft");
        var normalized = current.DeepClone().AsObject();
        if (normalized["proposal"] is JsonObject proposal && rejected["proposal"] is JsonObject rejectedProposal)
            proposal["severity"] = rejectedProposal["severity"]?.DeepClone();
        if (!JsonNode.DeepEquals(normalized, rejected))
            return Result(MortalJointRepairRawDisposition.Rejected, capture, JointRepairAdmissionIssue("Only the packet-owned severity leaf may be resubmitted."));
        if (capture.Packet.MatchesRejectedDecision(current))
            return Result(MortalJointRepairRawDisposition.Rejected, capture, capture.RejectedIssues.Select(BindMortalQteDraftRepairTarget).ToArray());
        var scene = guards[WoundNarrativeOutputPath] is { } sceneBytes ? ReadOrdinaryTreatmentRoot(sceneBytes, "joint resubmitted scene") : null;
        if (!capture.Packet.MatchesCorrectedDecision(current, scene?["response"]?.GetValue<string>()))
            // Preserve the original source-bound packet and hold across a still
            // invalid severity attempt; never replace it with a looser wave.
            return Result(MortalJointRepairRawDisposition.Rejected, capture, capture.RejectedIssues.Select(BindMortalQteDraftRepairTarget).ToArray());
        // Packet matching limits field ownership; it does not establish the
        // actual severity range. A still-invalid bounded leaf retains the
        // FIRST packet/checkpoint instead of minting a different repair wave.
        var attempted = MortalWoundOpportunityAdapter.ComposeQteAcceptedResponse(_fs, lease,
            CanonicalJsonUtf8.DecodeOneOptionalBom(draftBytes), scene!["response"]!.GetValue<string>(),
            out var replay, out var opportunity);
        if (attempted is { Success: false } && replay is null && opportunity is not null &&
            capture.Packet.MatchesOpportunity(opportunity) && attempted.Issues.Count > 0 &&
            attempted.Issues.All(issue => issue.Code == "wound_severity_above_opportunity"))
            return Result(MortalJointRepairRawDisposition.Rejected, capture, capture.RejectedIssues.Select(BindMortalQteDraftRepairTarget).ToArray());
        _ = await MortalJointRepairCheckpoint.RevalidateCorrectionAsync(_fs, lease, capture);
        return Result(MortalJointRepairRawDisposition.Owned, capture, Array.Empty<ValidationIssue>());
    }
    catch (Exception error) when (error is InvalidDataException or IOException or InvalidOperationException or ArgumentException or JsonException)
    { return Result(MortalJointRepairRawDisposition.Rejected, null, JointRepairAdmissionIssue(error.Message)); }
}

